        "Hot day ahead. Water crops in early morning or late evening to prevent high evaporation.": "తీవ్రమైన ఎండ. బాష్పీభవనం తగ్గించడానికి పంటలకు ఉదయం లేదా సాయంత్రం నీరు పెట్టండి.",
        "Cool weather. Ideal for winter rabi crops. Protect delicate seedlings from cold night frost.": "చల్లని వాతావరణం. రబీ పంటలకు అనుకూలం. రాత్రి చలి నుండి లేత మొలకలను రక్షించండి.",
        "High humidity. Monitor for fungal leaf blights. Ensure adequate field ventilation.": "అధిక తేమ. శిలీంధ్ర తెగుళ్ళను పర్యవేక్షించండి. పొలంలో గాలి ప్రసరణ ఉండేలా చూడండి.",
        "Favorable weather for farming activities. Ideal for soil preparation, irrigation and fertilization.": "వ్యవసాయ పనులకు అనుకూలమైన వాతావరణం. దుక్కి దున్నడం, నీరు మరియు ఎరువులకు అనువైన సమయం.",
        "AI-powered crop health, soil diagnostics, mandi locator & water planning": "ఏఐ పంట ఆరోగ్యం, నేల పరీక్ష, మార్కెట్ గుర్తింపు & నీటి ప్రణాళిక",
