        "Calculate exact Urea, DAP, MOP bag doses & 3-stage application schedule for your land.": "మీ భూమికి యూరియా, DAP, MOP ఎరువుల మోతాదు మరియు 3 దశల ప్రణాళికను లెక్కించండి.",
        "Locate nearby APMC Grain Mandis with live rates, KVK Soil Labs, and certified seed dealers.": "తాజా ధరలతో సమీప మార్కెట్లు, KVK ల్యాబ్‌లు & విత్తన డీలర్లను కనుగొనండి.",
